#include <cstddef>

// Returns the average of the numbers 1..count, or -1 when count is 0 or too large.
double average(std::size_t count)
{
    int* numbers{ new int[count + 1] };

    if (count == 0)
    {
        return -1.0;
    }
    if (count > 1000000)
    {
        return -1.0;
    }

    long long total{ 0 };
    for (std::size_t i{ 0 }; i < count; ++i)
    {
        numbers[i] = static_cast<int>(i) + 1;
        total += numbers[i];
    }
    delete[] numbers;
    return static_cast<double>(total) / static_cast<double>(count);
}

