#include <cstddef>

// Returns the average of the numbers 1..count, or -1 when count is 0 or too large.
double average(std::size_t count)
{
    if (count == 0 || count > 1000000)
    {
        return -1.0;
    }

    int* numbers{ new int[count] };
    long long total{ 0 };
    for (std::size_t i{ 0 }; i < count; ++i)
    {
        numbers[i] = static_cast<int>(i) + 1;
        total += numbers[i];
    }
    delete[] numbers;
    return static_cast<double>(total) / static_cast<double>(count);
}

unitTests:
TEST("still computes the average") { CHECK_NEAR(average(4), 2.5, 1e-9); CHECK_NEAR(average(100), 50.5, 1e-9); CHECK_NEAR(average(0), -1.0, 1e-9); CHECK_NEAR(average(2000000), -1.0, 1e-9); }
TEST("no leak on the normal path") { CHECK_NO_LEAK(average(500)); }
TEST("no leak when count is zero") { CHECK_NO_LEAK(average(0)); }
TEST("no leak when count is too large") { CHECK_NO_LEAK(average(5000000)); }

